import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const names = ['styles', 'shared', 'presentation', 'controller', 'components', 'library', 'panel', 'floating', 'entry'];
export function renderClientBundle() {
  const parts = names.map(name => {
    const file = join(root, 'src', 'ui', 'client', `${name}.mjs`);
    const source = readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
    const body = source.replace(/^import .+ from ['"]([^'"]+)['"];\s*$/gm, (_, dependency) => {
      if (dependency !== 'react' && !names.some(item => dependency === `./${item}.mjs`)) {
        throw new Error(`Unsupported client dependency: ${dependency}`);
      }
      return '';
    }).replace(/^export (?=(?:const|function|class)\b)/gm, '').trim();
    return `    // src/ui/client/${name}.mjs\n${body.split('\n').map(line => line.trim() ? `    ${line.trimEnd()}` : '').join('\n')}`;
  });
  return `// Generated by npm run build:client. Edit src/ui/client/ instead.\nwindow.__ModuleLoader__.load({\n  id: 'dsh-feiyufm-core',\n  factory: (require) => {\n    const React = require('react');\n${parts.join('\n\n')}\n    return { apply, inject: ['slots', 'connection', 'layout'] };\n  },\n});\n`;
}
export function buildClientBundle() {
  writeFileSync(join(root, 'src', 'ui', 'dsh-client.js'), renderClientBundle());
}
export function verifyClientBundle() {
  if (readFileSync(join(root, 'src', 'ui', 'dsh-client.js'), 'utf8').replace(/\r\n/g, '\n') !== renderClientBundle()) {
    throw new Error('DSH client is stale; run npm run build:client');
  }
}
